package com.umc.pediupatrao.audit;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document; import java.time.Instant; import java.util.Map;
@Document(collection="auditoria") public class Auditoria { @Id private String id; private String usuario; private String perfil; private Instant dataHora; private String operacao; private String entidade; private String entidadeId; private Map<String,Alteracao> camposAlterados; private String justificativa;
 public Auditoria(){} public Auditoria(String usuario,String perfil,Instant dataHora,String operacao,String entidade,String entidadeId,Map<String,Alteracao> camposAlterados,String justificativa){this.usuario=usuario;this.perfil=perfil;this.dataHora=dataHora;this.operacao=operacao;this.entidade=entidade;this.entidadeId=entidadeId;this.camposAlterados=camposAlterados;this.justificativa=justificativa;}
 public String getId(){return id;} public String getUsuario(){return usuario;} public String getPerfil(){return perfil;} public Instant getDataHora(){return dataHora;} public String getOperacao(){return operacao;} public String getEntidade(){return entidade;} public String getEntidadeId(){return entidadeId;} public Map<String,Alteracao> getCamposAlterados(){return camposAlterados;} public String getJustificativa(){return justificativa;}
 public static class Alteracao {private Object anterior;private Object novo;public Alteracao(){} public Alteracao(Object anterior,Object novo){this.anterior=anterior;this.novo=novo;} public Object getAnterior(){return anterior;} public Object getNovo(){return novo;}}
}
